"use client";

import React, { useState } from "react";

const photos = [
  { url: "https://images.unsplash.com/photo-1518199266791-5375a83190b7", caption: "Sunset Kisses" },
  { url: "https://images.unsplash.com/photo-1543163521-1bf539c55dd2", caption: "Beach Walks" },
  { url: "https://images.unsplash.com/photo-1516589174184-c68d8e574bd4", caption: "Coffee Mornings" },
  { url: "https://images.unsplash.com/photo-1494774157365-9e04c6720e47", caption: "Adventure Time" },
  { url: "https://images.unsplash.com/photo-1531747056595-07f6cb1b042b", caption: "Cozy Afternoons" },
  { url: "https://images.unsplash.com/photo-1513273159381-c4a0ef396162", caption: "Happy Smiles" },
];

const PhotoGallery = () => {
  const [selectedPhoto, setSelectedPhoto] = useState<{ url: string; caption: string } | null>(null);

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 py-8">
      {photos.map((photo, index) => (
        <div 
          key={index} 
          className="group relative bg-white p-4 pb-12 shadow-xl transform transition-transform hover:scale-105 hover:-rotate-1 cursor-pointer"
          onClick={() => setSelectedPhoto(photo)}
          style={{ transform: `rotate(${index % 2 === 0 ? "2" : "-2"}deg)` }}
        >
          <div className="overflow-hidden aspect-square rounded-sm">
            <img 
              src={`${photo.url}?auto=format&fit=crop&w=400&q=80`} 
              alt={photo.caption}
              className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
            />
          </div>
          <p className="absolute bottom-4 left-1/2 -translate-x-1/2 font-romantic text-lg text-romantic-text/80">
            {photo.caption}
          </p>
          <div className="absolute inset-4 ring-1 ring-inset ring-white/10 group-hover:ring-white/20 transition-all" />
        </div>
      ))}

      {/* Lightbox */}
      {selectedPhoto && (
        <div 
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-md transition-opacity animate-fade-in"
          onClick={() => setSelectedPhoto(null)}
        >
          <div className="max-w-4xl max-h-screen relative p-4 bg-white rounded-lg shadow-2xl glass">
            <img 
              src={`${selectedPhoto.url}?auto=format&fit=crop&w=1200&q=90`} 
              alt={selectedPhoto.caption}
              className="max-w-full max-h-[80vh] object-contain rounded-sm"
            />
            <p className="mt-4 text-center font-romantic text-2xl text-romantic-pink">
              {selectedPhoto.caption}
            </p>
            <button className="absolute top-2 right-2 text-3xl text-romantic-text/40 hover:text-romantic-pink">×</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default PhotoGallery;
