"use client";

import React, { useState, useRef, useEffect } from "react";

const MusicPlayer = () => {
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Soft romantic Lofi track
  const audioUrl = "https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3"; // Placeholder

  const togglePlay = () => {
    if (audioRef.current) {
      if (isPlaying) {
        audioRef.current.pause();
      } else {
        audioRef.current.play();
      }
      setIsPlaying(!isPlaying);
    }
  };

  return (
    <div className="fixed bottom-8 right-8 z-40 animate-fade-in" style={{ animationDelay: "1.5s" }}>
      <div className="flex items-center gap-3 bg-white/60 glass p-3 rounded-full shadow-lg group">
        <audio ref={audioRef} src={audioUrl} loop />
        
        {isPlaying && (
          <div className="flex items-end gap-1 h-6 px-2">
            <div className="w-1 bg-romantic-pink rounded-full animate-[ping_1s_infinite]" style={{ height: "40%" }} />
            <div className="w-1 bg-romantic-pink rounded-full animate-[ping_1.2s_infinite]" style={{ height: "80%" }} />
            <div className="w-1 bg-romantic-pink rounded-full animate-[ping_0.8s_infinite]" style={{ height: "60%" }} />
          </div>
        )}
        
        <div className="w-0 overflow-hidden group-hover:w-32 transition-all duration-500 whitespace-nowrap">
          <p className="text-xs font-romantic text-romantic-pink opacity-0 group-hover:opacity-100 transition-opacity">
            Playing: Soft Romantic Lofi 🎵
          </p>
        </div>

        <button 
          onClick={togglePlay}
          className="w-12 h-12 flex items-center justify-center rounded-full bg-romantic-pink text-white shadow-md hover:bg-pink-400 transition-all hover:scale-110"
        >
          {isPlaying ? (
            <span className="text-xl">⏸️</span>
          ) : (
            <span className="text-xl">▶️</span>
          )}
        </button>
      </div>
    </div>
  );
};

export default MusicPlayer;
