"use client";

import React, { useEffect, useState } from "react";

const CursorHearts = () => {
  const [points, setPoints] = useState<{ id: number; x: number; y: number; opacity: number }[]>([]);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      const newPoint = {
        id: Date.now(),
        x: e.clientX,
        y: e.clientY,
        opacity: 1,
      };
      setPoints((prev) => [...prev.slice(-15), newPoint]);
    };

    window.addEventListener("mousemove", handleMouseMove);
    return () => window.removeEventListener("mousemove", handleMouseMove);
  }, []);

  useEffect(() => {
    const timer = setInterval(() => {
      setPoints((prev) => 
        prev.map(p => ({ ...p, opacity: p.opacity - 0.05 }))
            .filter(p => p.opacity > 0)
      );
    }, 50);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="fixed inset-0 pointer-events-none z-[100]">
      {points.map((p) => (
        <div 
          key={p.id}
          className="absolute text-pink-400 select-none"
          style={{ 
            left: p.x, 
            top: p.y, 
            opacity: p.opacity,
            transform: `translate(-50%, -50%) scale(${p.opacity})`,
            fontSize: "1.2rem"
          }}
        >
          ❤️
        </div>
      ))}
    </div>
  );
};

export default CursorHearts;
